<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import TrafficVideo from '../components/TrafficVideo.vue'
import BackendLayout from '../components/BackendLayout.vue'
import ServiceFields from '../components/ServiceFields.vue'
import {backendResources,resourceRoutes,valueLabels,type Field,type Action} from '../data/backendResources'
import {backend,asPage,queryString,downloadPdf,type PageData} from '../services/backend'
import {useApp} from '../stores/app'
const route=useRoute(),app=useApp(),resourceId=computed(()=>String(route.params.resource||resourceRoutes[route.path]||'facilities')),resource=computed(()=>backendResources[resourceId.value]),customer=computed(()=>resource.value?.owner||['/c-notice','/info/faq','/customer-app/notices','/customer-app/faq'].includes(route.path))
const relatedIds=computed(()=>{const groups=[['facilities','cameras','thresholds','transits','events','reviews','transfers','risk-history'],['managers','regions','shifts'],['display','presets','reasons'],['customers','inquiries','notices','faqs','alerts']];return groups.find(group=>group.includes(resourceId.value))||[]})
const canWrite=computed(()=>resource.value?.owner?app.account?.role==='customer':!customer.value&&app.account?.role==='REGIONAL_ADMIN')
const filters=reactive<Record<string,any>>({}),parents=reactive<Record<string,any>>({}),choices=reactive<Record<string,{value:string;label:string}[]>>({}),values=reactive<Record<string,any>>({})
const acknowledge=ref(false)
const data=ref<PageData<Record<string,any>>>({items:[],page:1,size:20,totalItems:0,totalPages:0}),page=ref(1),loading=ref(false),error=ref(''),message=ref(''),saving=ref(false),modal=ref<HTMLDialogElement>(),selected=ref<Record<string,any>|null>(null),mode=ref(''),formFields=ref<Field[]>([]),action=ref<Action>(),detail=ref<Record<string,any>>({})
let abort:AbortController|undefined,request=0,alive=true
function path(template:string,row=selected.value){return template.replace(/\{(\w+)\}/g,(_,key)=>encodeURIComponent(String(key==='id'?row?.[resource.value.rowKey||'id']:parents[key]??row?.[key]??'')))}
const missingParent=computed(()=>resource.value?.parents?.some(field=>field.required&&!parents[field.key]))
async function lookup(fields:Field[],row?:Record<string,any>){const scope=resourceId.value;for(const field of fields){if(!field.source)continue;let url=field.source==='underpasses'?'/api/underpasses?size=500':field.source==='regions'?'/api/regions':field.source==='shifts'?'/api/shifts':field.source==='presets'?'/api/display/presets':field.source==='reasons'?'/api/control/reason-presets':`/api/underpasses/${row?.id||parents.underpassId}/cameras`;if(field.source==='cameras'&&!row?.id&&!parents.underpassId)continue;try{const result=await backend(url);if(alive&&scope===resourceId.value&&(!row||selected.value?.id===row.id))choices[field.key]=asPage<any>(result).items.map(item=>({value:String(item.id),label:item.name||item.content||`${item.cameraRole} · ${item.id}`}))}catch{/* Main list retains its own request error. */}}}
async function load(){if(!resource.value||missingParent.value)return;abort?.abort();abort=new AbortController();const seq=++request;loading.value=true;error.value='';try{if(filters.startDate&&filters.endDate&&filters.startDate>filters.endDate)throw new Error('시작일은 종료일보다 늦을 수 없습니다.');const result=await backend(path(resource.value.path)+queryString({...filters,page:page.value,size:20}),{signal:abort.signal});if(seq===request)data.value=asPage(result,page.value)}catch(e){if(seq===request&&!abort.signal.aborted)error.value=(e as Error).message}finally{if(seq===request)loading.value=false}}
function imageUrl(value:string){if(!value)return '';const parts=value.replace(/^\/api\/uploads\//,'').split(/[\\/]/);if(parts.some(part=>part==='..'||part==='.')||value.includes(':'))return '';return '/api/uploads/'+parts.filter(Boolean).map(encodeURIComponent).join('/')}
function display(value:any){if(value==null||value==='')return '—';if(typeof value==='boolean')return value?'예':'아니요';if(Array.isArray(value))return value.map(item=>typeof item==='object'?item.name||item.id:item).join(', ');if(typeof value==='object')return value.name||'—';return valueLabels[String(value)]||String(value).replace('T',' ')}
function openDialog(){if(modal.value&&!modal.value.open)modal.value.showModal()}
async function open(kind:string,row?:Record<string,any>,itemAction?:Action){acknowledge.value=false;selected.value=row||null;mode.value=kind;action.value=itemAction;error.value='';message.value='';Object.keys(values).forEach(key=>delete values[key]);detail.value=row||{};formFields.value=kind==='remove'||kind==='detail'||kind==='video'?[]:kind==='action'?itemAction?.fields||[]:resource.value.fields||[];try{if(row&&resource.value.detail){detail.value=await backend(`${path(resource.value.path)}/${encodeURIComponent(row.id)}`)}for(const field of formFields.value){const value=field.key==='eventId'?detail.value.currentBlockEventId:field.key==='content'&&resourceId.value==='inquiries'&&kind==='action'?(itemAction?.method==='POST'?'':detail.value.replyContent):field.key==='correctedNum'?(detail.value.correctedNum||detail.value.detectedNum):detail.value[field.key];values[field.key]=field.type==='multi'?(Array.isArray(value)?value.map(v=>String(v.id||v)):[]):field.type==='checkbox'?Boolean(value):Array.isArray(value)?value.join('\n'):value==null?'':String(value)}void lookup(formFields.value,row);openDialog()}catch(e){error.value=(e as Error).message}}
function body(){const result:Record<string,unknown>={};for(const field of formFields.value){const value=values[field.key];if(field.type==='multi')result[field.key]=(value||[]).map(Number);else if(field.type==='lines')result[field.key]=String(value||'').split(/\n/).map(v=>v.trim()).filter(Boolean);else if(field.type==='checkbox')result[field.key]=Boolean(value);else if(field.type==='number'||field.source)result[field.key]=value===''?null:Number(value);else result[field.key]=value===''?null:value}return result}
async function submit(){if(saving.value)return;saving.value=true;error.value='';try{if(resourceId.value==='display'&&mode.value!=='remove'&&!values.presetId&&!String(values.content||'').trim())throw new Error('문구를 선택하거나 입력해 주세요.');if(resourceId.value==='customers'&&mode.value==='edit'&&!acknowledge.value)throw new Error('주소·비상 연락처 교체 내용을 확인해 주세요.');let url=path(resource.value.path),method='POST',pdf=false,payload:unknown=body();if(mode.value==='edit'){url+=`/${encodeURIComponent(selected.value?.[resource.value.rowKey||'id'])}`;method='PUT'}if(mode.value==='remove'){url+=`/${encodeURIComponent(selected.value?.[resource.value.rowKey||'id'])}`;method='DELETE';payload=undefined}if(mode.value==='action'&&action.value){url=path(action.value.path);method=action.value.method||'POST';pdf=!!action.value.pdf;if(!formFields.value.length)payload=undefined}const result=await backend(url,{method,body:payload,pdf});if(pdf)downloadPdf(result,`이관문서-${selected.value?.id||'시설'}.pdf`);modal.value?.close();message.value='요청이 처리되었습니다.';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function search(){page.value=1;void load()}
function navigatePage(next:number){page.value=next;void load()}
const labels=computed(()=>Object.fromEntries([...resource.value.columns,...(resource.value.fields||[]).map(field=>[field.key,field.label]),['content','내용'],['answer','답변'],['replyContent','답변 내용'],['replyAuthorName','답변자'],['repliedAt','답변일'],['roadAddress','주소']]))
watch(()=>route.fullPath,()=>{abort?.abort();request++;modal.value?.close();for(const obj of [filters,parents,choices])Object.keys(obj).forEach(key=>delete obj[key]);page.value=1;data.value={items:[],page:1,size:20,totalItems:0,totalPages:0};error.value='';if(!resource.value){error.value='페이지를 찾을 수 없습니다.';return}for(const field of resource.value.parents||[])parents[field.key]=route.query[field.key]||'';for(const field of resource.value.filters||[])if(route.query[field.key])filters[field.key]=route.query[field.key];if(resourceId.value==='reviews'&&!filters.reviewStatus)filters.reviewStatus='PENDING';void lookup([...(resource.value.parents||[]),...(resource.value.filters||[])]);void load().then(()=>{if(route.query.id&&resource.value.detail)void open('detail',{id:Number(route.query.id)})})},{immediate:true})
onBeforeUnmount(()=>{alive=false;abort?.abort();modal.value?.close()})
</script>
<template><component :is="customer?'div':BackendLayout"><section v-if="resource" class="service-workspace"><div class="service-heading"><h1>{{resource.title}}</h1><div class="service-actions"><button type="button" :disabled="loading||missingParent" @click="load">새로고침</button><button v-if="resource.create&&canWrite" type="button" @click="open('create')">새로 등록</button></div></div><nav v-if="!customer" class="service-tabs" aria-label="관리 기능"><RouterLink v-for="id in relatedIds" :key="id" :to="'/admin-data/'+id">{{backendResources[id]?.title}}</RouterLink></nav><form class="service-filters" @submit.prevent="search"><ServiceFields v-if="resource.parents?.length" :fields="resource.parents" :values="parents" :choices="choices"/><ServiceFields v-if="resource.filters?.length" :fields="resource.filters" :values="filters" :choices="choices"/><button type="submit" :disabled="loading">조회</button></form><p v-if="error" class="service-error" role="alert">{{error}} <RouterLink v-if="!app.account" :to="customer?'/login':'/admin-login'">로그인</RouterLink></p><p v-if="message" class="service-message" role="status">{{message}}</p><p v-if="missingParent">위에서 {{resource.parents?.map(field=>field.label).join(' · ')}}를 선택하고 조회하세요.</p><p v-else-if="loading" role="status">불러오는 중입니다.</p><template v-else><div class="service-table-wrap"><table class="service-table"><thead><tr><th v-for="[key,label] in resource.columns" :key="key">{{label}}</th><th>상세·처리</th></tr></thead><tbody><tr v-for="(row,index) in data.items" :key="row.id||index"><td v-for="[key] in resource.columns" :key="key"><img v-if="key==='imagePath'&amp;&amp;imageUrl(row[key])&amp;&amp;!row.imageUnavailable" :src="imageUrl(row[key])" alt="번호판 인식 이미지" loading="lazy" @error="row.imageUnavailable=true"><template v-else>{{key==='imagePath'?'이미지 없음':display(row[key])}}</template></td><td><div class="service-actions"><button v-if="resourceId==='cameras'&amp;&amp;row.streamUrl" @click="open('video',row)">영상 보기</button><button v-if="resource.detail" @click="open('detail',row)">상세 보기</button><button v-if="resource.edit&&canWrite" @click="open('edit',row)">수정</button><button v-if="resource.remove&&canWrite" @click="open('remove',row)">삭제</button><button v-for="act in canWrite?resource.actions||[]:[]" :key="act.label" @click="open('action',row,act)">{{act.label}}</button><RouterLink v-if="resourceId==='facilities'" :to="'/admin-data/cameras?underpassId='+row.id">카메라·입출구</RouterLink></div></td></tr><tr v-if="!data.items.length"><td :colspan="resource.columns.length+1">조회된 항목이 없습니다.</td></tr></tbody></table></div><div class="service-pagination"><button :disabled="page<=1" @click="navigatePage(page-1)">이전</button><span>{{page}} / {{Math.max(1,data.totalPages)}} · {{data.totalItems}}건</span><button :disabled="page>=data.totalPages" @click="navigatePage(page+1)">다음</button></div></template><dialog ref="modal" class="service-modal" @close="mode=''"><form @submit.prevent="submit"><header><h2>{{mode==='video'?'카메라 영상':mode==='detail'?'상세 보기':mode==='create'?'새로 등록':mode==='edit'?'정보 수정':mode==='remove'?'삭제 확인':action?.label}}</h2><button type="button" :disabled="saving" @click="modal?.close()">닫기</button></header><TrafficVideo v-if="mode==='video'" :src="selected?.streamUrl" :hls="true"/><img v-if="resourceId==='reviews'&amp;&amp;imageUrl(selected?.imagePath)" :src="imageUrl(selected?.imagePath)" alt="확인할 번호판" style="max-width:100%;max-height:300px;object-fit:contain"><dl v-if="mode==='detail'" class="service-detail"><template v-for="(label,key) in labels" :key="key"><template v-if="detail[key]!=null"><dt>{{label}}</dt><dd>{{display(detail[key])}}</dd></template></template></dl><div v-if="mode==='detail'&&canWrite" class="service-actions"><button v-for="act in resource.actions||[]" :key="act.label" type="button" @click="open('action',detail,act)">{{act.label}}</button></div><template v-if="mode!=='detail'&amp;&amp;mode!=='video'"><p v-if="mode==='remove'">선택한 항목을 삭제하시겠습니까?</p><p v-else-if="mode==='action'&&!formFields.length">선택한 항목에 대해 {{action?.label}} 작업을 진행하시겠습니까?</p><div v-if="resourceId==='customers'&amp;&amp;mode==='edit'" class="service-message"><p>목록에는 기존 주소·비상 연락처가 제공되지 않습니다. 저장하면 해당 항목도 입력한 값으로 교체됩니다.</p><label><input v-model="acknowledge" type="checkbox" required> 주소·비상 연락처 교체를 확인했습니다.</label></div><ServiceFields :fields="formFields" :values="values" :choices="choices" :disabled="saving"/></template><p v-if="error" class="service-error" role="alert">{{error}}</p><footer v-if="mode!=='detail'&amp;&amp;mode!=='video'"><button type="button" :disabled="saving" @click="modal?.close()">취소</button><button type="submit" :disabled="saving">{{saving?'처리 중…':'확인'}}</button></footer></form></dialog></section><p v-else role="alert">페이지를 찾을 수 없습니다.</p></component></template>
